'use strict';
const content=document.getElementById('content'),platform=document.getElementById('platform'),surface=document.getElementById('play-surface'),frame=document.getElementById('game-frame');
const frames={minesweeper:frame,rocket:document.getElementById('rocket-frame')};
const session={visited:false,loaded:false,activeGame:'minesweeper',loadedGames:new Set(),points:1000,rounds:[],ledger:[{label:'首次体验赠送',amount:1000,time:'本次会话'}],claims:new Set(),finished:new Set()};let page='games',filter='全部';
const catalog=[{id:'minesweeper',name:'金币扫雷',category:'益智',duration:'约 3 分钟',cover:'sweep-cover',art:'<span class="cover-sprite" aria-hidden="true"></span>',available:true},{id:'rocket',name:'小火箭',category:'反应',duration:'主动收取 · 50 积分 / 局',cover:'cover-rocket',art:'<img class="rocket-cover-image" src="rocket-web3.png" alt="">',available:true},{id:'2048',name:'2048',category:'益智',duration:'合并数字',cover:'cover-2048',art:'<span class="cover-number">2048</span>'},{id:'memory',name:'记忆翻牌',category:'益智',duration:'配对挑战',cover:'cover-memory',art:'<span aria-hidden="true">▣ ▣</span>'},{id:'rhythm',name:'节奏点击',category:'反应',duration:'节奏挑战',cover:'cover-rhythm',art:'<span aria-hidden="true">ϟ</span>'}];
function showPage(next){page=['games','rewards','me'].includes(next)?next:'games';platform.hidden=false;surface.hidden=true;if(session.loadedGames.has('minesweeper'))frame.contentWindow.postMessage({type:'platform-pause',paused:true},location.origin);document.querySelectorAll('.navigation button').forEach(b=>{if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});render();window.scrollTo(0,0)}
function render(){if(page==='games'){const games=catalog.filter(g=>filter==='全部'||g.category===filter);content.innerHTML=`<div class="welcome"><div><h1>今天，玩点什么？</h1><p class="muted">轻松开局，随时来一局。</p></div><span class="session-chip">模拟积分 ${session.points.toLocaleString()}</span></div>${session.visited?`<div class="continue"><div class="continue-symbol" aria-hidden="true">${session.activeGame==='rocket'?'↗':'◈'}</div><div><h2>${gameName(session.activeGame)}</h2><p class="muted">最近玩过</p></div><button class="primary" data-play="${session.activeGame}">回到游戏</button></div>`:''}<div class="section-row"><h2>探索游戏</h2><div class="filters" aria-label="游戏分类">${['全部','益智','反应'].map(c=>`<button class="filter" data-filter="${c}" aria-pressed="${filter===c}">${c}</button>`).join('')}</div></div><div class="catalog">${games.map(g=>`<button class="game-card" ${g.available?`data-play="${g.id}"`:'disabled'} aria-label="${g.name}${g.available?'，开始游戏':'，即将上线'}"><div class="cover ${g.cover}">${g.available?'<span class="game-label">现在就玩</span>':''}${g.art}</div><div class="game-details"><div class="game-title-row"><h2>${g.name}</h2></div><p>${g.duration}</p><div class="card-bottom"><span class="tag">${g.category}</span><span class="${g.available?'play-label':'coming'}">${g.available?'开始游戏 ↗':'即将上线'}</span></div></div></button>`).join('')}</div><p class="catalog-footer">更多游戏正在筹备中</p>`}else if(page==='rewards'){content.innerHTML=`<h1>我的奖励</h1><p class="muted">游戏积分与链上资产，分别查看。</p><div class="panel-grid"><section class="panel"><h2>本次体验积分</h2><div class="balance">${session.points}<span>积分</span></div><p class="muted">首次赠送 1,000 积分；扫雷通关可领取 440 积分。</p></section><section class="panel"><h2>链上资产</h2><div class="empty">尚未接入钱包</div><p class="muted">当前版本没有充值、提现或真实交易。</p></section></div><section class="panel list-panel"><h2>积分明细</h2>${session.ledger.slice().reverse().map(r=>`<div class="record"><div>${r.label}<small>${r.time}</small></div><span class="${r.amount>0?'positive':'muted'}">${r.amount>0?'+':''}${r.amount} 积分</span></div>`).join('')}</section><p class="notice">积分仅用于本次 Demo 体验，刷新后重置为初始赠送积分，不具有货币价值。</p>`}else{content.innerHTML=`<h1>我的</h1><div class="profile"><span class="avatar">P</span><div><h2>游客玩家</h2><p class="muted">先玩一局，轻松探索</p></div></div><div class="panel-grid"><section class="panel"><h2>本次游戏记录</h2>${session.rounds.length?session.rounds.slice().reverse().map(r=>`<div class="record"><div>${gameName(r.gameId)}<small>${r.time} · ${r.seconds} 秒</small></div><span class="${r.won?'positive':'muted'}">${r.gameId==='rocket'?(r.won?'已收取 '+r.amount+' 积分':'已坠毁 · 0 积分'):(r.won?'已通关':'踩到地雷')}</span></div>`).join(''):'<div class="empty">还没有完成的游戏。</div><button class="primary" data-play>开始第一局</button>'}</section><section><div class="rows"><button class="row-button" data-help="account"><span>账户与钱包</span><span>未接入 ›</span></button><button class="row-button" data-help="rules"><span>玩法说明</span><span>游戏规则 ›</span></button><button class="row-button" data-help="about"><span>关于 PLAYROOM</span><span>Demo ›</span></button></div><p class="notice">游戏记录仅保留在本次页面会话中。</p></section></div>`}}
function gameName(id){return id==='rocket'?'小火箭':'金币扫雷'}
function timeLabel(){return new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}
function addLedger(label,amount){session.ledger.push({label,amount,time:timeLabel()})}
const rocketRound=new RocketRound({charge(cost){if(session.points<cost)return false;session.points-=cost;addLedger('小火箭 · 发射消耗',-cost);return true},credit(amount){session.points+=amount;addLedger('小火箭 · 主动收取',amount)},onFinish(r){session.rounds.push({...r,time:timeLabel()});if(!r.won)addLedger('小火箭 · 坠毁，奖励归零',0);if(!platform.hidden)render()}});
function syncRocket(){if(session.loadedGames.has('rocket')){rocketRound.tick();frames.rocket.contentWindow.postMessage(rocketRound.snapshot(session.points),location.origin)}}
function play(id='minesweeper'){if(!frames[id])return;session.visited=true;session.activeGame=id;platform.hidden=true;surface.hidden=false;for(const [key,f] of Object.entries(frames)){f.hidden=key!==id;if(key==='minesweeper'&&session.loadedGames.has(key))f.contentWindow.postMessage({type:'platform-pause',paused:key!==id},location.origin)}if(!session.loadedGames.has(id)){frames[id].src=id==='rocket'?'rocket.html':'minesweeper.html';session.loadedGames.add(id);session.loaded=true}else if(id==='rocket')syncRocket();window.scrollTo(0,0)}

function help(kind){const copy={account:['账户与钱包','当前使用游客模式，无需注册即可试玩。\n账户绑定和钱包连接尚未接入。'],rules:['游戏怎么玩？','金币上的数字表示周围 8 格中的地雷数量。\n揭开全部 44 个安全方块即可通关；用插旗模式或鼠标右键标记疑似地雷。\n首次点击安全。通关后可领取 440 模拟积分。\n\n小火箭：每局消耗 50 积分。飞行越久倍率越高，可随时主动收取；坠毁前未收取则本局奖励归零。收取得分含本局投入，切出页面不会暂停。'],about:['关于 PLAYROOM','一个轻量休闲游戏平台 Demo。\n当前可玩：金币扫雷、小火箭。其他游戏正在筹备中。\n所有奖励均为模拟积分，不涉及真实资产。']};document.getElementById('help-title').textContent=copy[kind][0];document.getElementById('help-text').textContent=copy[kind][1];document.getElementById('help').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-play'))play(b.dataset.play||'minesweeper');else if(b.dataset.page){location.hash=b.dataset.page;showPage(b.dataset.page)}else if(b.dataset.filter){filter=b.dataset.filter;render()}else if(b.dataset.help)help(b.dataset.help)});
for(const id of ['help-close','help-ok'])document.getElementById(id).onclick=()=>document.getElementById('help').close();window.addEventListener('hashchange',()=>showPage(location.hash.slice(1)));
window.addEventListener('message',e=>{if(e.origin!==location.origin||!e.data||typeof e.data!=='object')return;const gameId=Object.keys(frames).find(id=>frames[id].contentWindow===e.source);if(!gameId||!session.loadedGames.has(gameId))return;const d=e.data;if(d.type==='game-return'){showPage('games');return}if(gameId==='rocket'){if(d.type==='rocket-launch'){if(!rocketRound.start())frames.rocket.contentWindow.postMessage({type:'rocket-error',message:rocketRound.state==='flying'?'已有火箭在飞行。':'积分不足，可以先玩扫雷赚取积分。'},location.origin)}else if(d.type==='rocket-collect')rocketRound.collect();if(['rocket-ready','rocket-launch','rocket-collect'].includes(d.type))syncRocket();return}
const key='minesweeper:'+d.roundId;if(d.type==='game-finished'&&typeof d.roundId==='string'&&!session.finished.has(key)&&typeof d.won==='boolean'&&Number.isInteger(d.seconds)&&d.seconds>=0){session.finished.add(key);session.rounds.push({id:key,gameId:'minesweeper',won:d.won,seconds:d.seconds,amount:440,claimed:false,time:timeLabel()})}else if(d.type==='game-reward'&&typeof d.roundId==='string'&&!session.claims.has(key)){const round=session.rounds.find(r=>r.id===key&&r.won);if(!round)return;session.claims.add(key);round.claimed=true;session.points+=440;addLedger('金币扫雷 · 通关奖励',440);syncRocket()}if(!platform.hidden)render()});
setInterval(syncRocket,100);

showPage(location.hash.slice(1));
